import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`vs-grok`,hasInputUrl:!1,heroTitle:`Grok the Problem. Computer Solves It`,heroSubtitle:`Perplexity Computer researches, builds, and executes multi-step workflows across 19 AI models — automatically.`,heroOverlaySteps:[`Analyzing your request and breaking it into specialized tasks`,`Spinning up agents matched to the best AI model for each step`,`Executing your workflow across the web and connected tools`,`Polished deliverables compiled and formatted — ready to use`],generatingSteps:[`Parsing your task to identify every step and deliverable`,`Designing an agent to handle each subtask with the optimal AI model`,`Configuring web browsing, tool connections, and output formatting`,`Setting up your complete workflow with real-time progress tracking`],featureSectionTitle:`From prompt to finished work`,featureCardTitles:[`Connects to your entire stack`,`Outputs you can ship`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Docs, Gmail, Slack, Notion, GitHub, Airtable — Computer plugs into the tools you already use so work flows end-to-end.`,`Research reports. Competitive analyses. Spreadsheets with real data. Code commits. Formatted documents — not chat responses you have to rewrite.`],capabilitySectionTitle:`Your AI workforce, on autopilot`,capabilitySectionSubtitle:`Describe what you need, step away, come back to finished work.`,capabilityCards:[{title:`Deep Research`,description:`Computer can browse the live web, synthesize dozens of sources, and deliver structured research — not static training data.`},{title:`Multi-Step Execution`,description:`Computer can chain complex tasks together — research, analyze, write, format, and deliver — instead of stopping at a single chat response.`},{title:`Real Deliverables`,description:`Computer can produce spreadsheets, documents, reports, and code — polished outputs ready to use, not conversation threads you copy-paste from.`},{title:`Connect Your Tools`,description:`Computer can read and write to Google Sheets, Gmail, Slack, Notion, GitHub, and more — build workflows across your entire stack.`},{title:`Memory & Context`,description:`Computer can remember your preferences, past projects, and key details across sessions — so every workflow builds on what it already knows about you.`},{title:`Monitor & Alert`,description:`Computer can run workflows on a schedule and alert you when something changes — competitor moves, data shifts, or new opportunities worth acting on.`}]});export{t as default};
